CREATE OR REPLACE FUNCTION get_appraisal_score(p_ticker character varying)
RETURNS numeric AS $$
DECLARE
    v_alpha3y real;
    v_volatility3y real;
    v_rsquared3y real;
    v_unsystematic_risk real;
BEGIN
    SELECT alpha3y, volatility3y, rsquared3y 
    INTO v_alpha3y, v_volatility3y, v_rsquared3y
    FROM risk_metrics 
    WHERE investmentref = p_ticker;

    IF v_alpha3y IS NULL OR v_volatility3y IS NULL OR v_rsquared3y IS NULL THEN
        RETURN NULL;
    END IF;

    IF v_volatility3y <= 0 OR v_rsquared3y >= 100 THEN
        RETURN NULL;
    END IF;

    v_unsystematic_risk := v_volatility3y * SQRT(1 - v_rsquared3y / 100.0);

    IF v_unsystematic_risk = 0 THEN
        RETURN NULL;
    END IF;

    RETURN ROUND(CAST(v_alpha3y / v_unsystematic_risk AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

CREATE OR REPLACE FUNCTION get_appraisal_score(p_ticker character varying)
RETURNS numeric AS $$
DECLARE
    v_alpha3y real;
    v_volatility3y real;
    v_rsquared3y real;
BEGIN
    SELECT alpha3y, volatility3y, rsquared3y 
    INTO v_alpha3y, v_volatility3y, v_rsquared3y
    FROM risk_metrics 
    WHERE investmentref = p_ticker;

    IF v_alpha3y IS NULL OR v_volatility3y IS NULL OR v_rsquared3y IS NULL THEN
        RETURN NULL;
    END IF;

    IF v_volatility3y <= 0 OR v_rsquared3y >= 100 THEN
        RETURN NULL;
    END IF;

    RETURN ROUND(CAST(v_alpha3y / (v_volatility3y * SQRT(1 - v_rsquared3y / 100.0)) AS numeric), 4);
END;
$$ LANGUAGE plpgsql;

